onClick:
{{
  (async function() {
    try {
      // 1. Passage du statut à "Envoi n8n en cours"
      await Update_Statut_Action_Devis.run({ statut: "Envoi n8n en cours" });
      showAlert("Génération et envoi du devis Pennylane lancés...", "info");

      await Get_Devis_Detail.run();

      // 2. Configuration du timeout (30 secondes max)
      let attempts = 0;
      const maxAttempts = 30; // 12 * 2,5s = 30 secondes

      setInterval(() => {
        attempts++;

        // SÉCURITÉ : Si n8n ne répond pas après 30 secondes
        if (attempts > maxAttempts) {
          clearInterval("polling_pdf_devis");
          showAlert("Délai dépassé : n8n prend trop de temps ou a planté.", "error");
          Get_Devis_Detail.run(); // Rafraîchissement final
          return;
        }

        // Vérification du statut
        Get_Devis_Detail.run().then((data) => {
          const statut_actuel = data[0]?.STATUT;

          if (statut_actuel !== "Envoi n8n en cours") {
            clearInterval("polling_pdf_devis");

            if (statut_actuel === "PDF Prêt" || statut_actuel === "Brouillon") {
              showAlert("Le PDF est généré et prêt !", "success");
            } else {
              showAlert("Traitement terminé (Statut : " + statut_actuel + ")", "warning");
            }
          }
        });
      }, 1000, "polling_pdf_devis");

    } catch (error) {
      showAlert("Erreur lors du lancement de l'envoi : " + error.message, "error");
    }
  })()
}}
